import type { PracticalGuide } from './practical-guide-data.ts';

const encryptedDocuments = {
  en: 'The browser encrypts document contents before upload. Utilibre stores encrypted documents and functional account/storage metadata. Editing and viewing links may contain keys; recipients can keep copies. Exported office/text files are not automatically encrypted. Browser delivery still relies on trusted server code. Keep your own account recovery material and exports; email alone cannot recover a lost encrypted account.',
  es: 'El navegador cifra el contenido antes de subirlo. Utilibre guarda documentos cifrados y metadatos funcionales de cuenta y almacenamiento. Los enlaces de edición y lectura pueden contener claves; los destinatarios pueden conservar copias. Los archivos exportados no quedan cifrados automáticamente. Dependés de que el servidor entregue código confiable. Conservá la recuperación de tu cuenta y tus exportaciones; el correo por sí solo no recupera una cuenta cifrada perdida.',
};

// Native application instructions; access and destinations remain in the catalogue.
